import itertools

def solve_small_n(n):
    perms = list(itertools.permutations(range(n)))
    total_sum = 0
    for p in perms:
        # sign of permutation
        sign = 1
        visited = [False] * n
        for i in range(n):
            if not visited[i]:
                count = 0
                curr = i
                while not visited[curr]:
                    visited[curr] = True
                    curr = p[curr]
                    count += 1
                if count % 2 == 0:
                    sign *= -1

        # number of fixed points
        fixed_points = 0
        for i in range(n):
            if p[i] == i:
                fixed_points += 1

        total_sum += sign / (fixed_points + 1)
    return total_sum

for n in range(1, 7):
    print(f"n={n}, sum={solve_small_n(n)}")
